<?php
namespace ProjectPress\API;
use ProjectPress\Includes\Project\Composition\CompositionRepository;use ProjectPress\Includes\Project\Composition\CompositionService;use ProjectPress\Includes\Project\Composition\SBOMService;use ProjectPress\Includes\Project\Core\ProjectPermissions;use ProjectPress\Includes\Project\ProjectManager;use WP_Error;use WP_REST_Request;use WP_REST_Response;use WP_REST_Server;
if(!defined('ABSPATH')){exit;}
final class CompositionRoutes{
 private const TYPES=array('components'=>'component','packages'=>'package','assets'=>'asset','licences'=>'licence','attributions'=>'attribution','provenance'=>'provenance','relationships'=>'relationship','sboms'=>'sbom');
 public static function register_routes():void{register_rest_route(Routes::NAMESPACE,'/projects/(?P<project>[A-Za-z0-9_-]+)/composition/snapshot',array('methods'=>WP_REST_Server::READABLE,'callback'=>array(self::class,'snapshot'),'permission_callback'=>array(self::class,'can_read')));register_rest_route(Routes::NAMESPACE,'/projects/(?P<project>[A-Za-z0-9_-]+)/composition/(?P<type>components|packages|assets|licences|attributions|provenance|relationships|sboms)',array(array('methods'=>WP_REST_Server::READABLE,'callback'=>array(self::class,'index'),'permission_callback'=>array(self::class,'can_read')),array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array(self::class,'create'),'permission_callback'=>array(self::class,'can_edit'))));register_rest_route(Routes::NAMESPACE,'/projects/(?P<project>[A-Za-z0-9_-]+)/composition/(?P<type>components|packages|assets|licences|attributions|provenance|relationships|sboms)/(?P<id>\d+)',array(array('methods'=>WP_REST_Server::EDITABLE,'callback'=>array(self::class,'update'),'permission_callback'=>array(self::class,'can_edit')),array('methods'=>WP_REST_Server::DELETABLE,'callback'=>array(self::class,'delete'),'permission_callback'=>array(self::class,'can_edit'))));}
 public static function snapshot(WP_REST_Request$r){$p=self::project($r);if(is_wp_error($p))return$p;$data=(new SBOMService(ProjectManager::get_instance()->repository(),new ProjectPermissions()))->snapshot($p->get_id());return null===$data?self::not_found(__('Composition snapshot unavailable.','projectpress')):self::success($data);}
 public static function index(WP_REST_Request$r){$p=self::project($r);if(is_wp_error($p))return$p;$repo=self::repo($r);return self::success(array_map(static fn($x)=>$x->to_array(),$repo->for_project($p->get_id())));}
 public static function create(WP_REST_Request$r){$p=self::project($r);if(is_wp_error($p))return$p;$repo=self::repo($r);return self::domain(self::service($r,$repo)->create($p->get_id(),self::input($r)),201);}
 public static function update(WP_REST_Request$r){$p=self::project($r);if(is_wp_error($p))return$p;$repo=self::repo($r);$record=$repo->find(absint($r['id']));if(!$record||$record->get_project_id()!==$p->get_id())return self::not_found(__('Composition record not found.','projectpress'));return self::domain(self::service($r,$repo)->update($record,self::input($r)));}
 public static function delete(WP_REST_Request$r){$p=self::project($r);if(is_wp_error($p))return$p;$repo=self::repo($r);$record=$repo->find(absint($r['id']));if(!$record||$record->get_project_id()!==$p->get_id())return self::not_found(__('Composition record not found.','projectpress'));$x=self::service($r,$repo)->delete($record);return is_wp_error($x)?$x:self::success(array('deleted'=>(bool)$x,'id'=>$record->get_id()));}
 public static function can_read(WP_REST_Request$r){$p=self::project($r);return is_wp_error($p)?$p:((new ProjectPermissions())->can_view($p)?true:self::forbidden());}public static function can_edit(WP_REST_Request$r){$p=self::project($r);return is_wp_error($p)?$p:((new ProjectPermissions())->can_edit($p)?true:self::forbidden());}
 private static function project(WP_REST_Request$r){$p=ProjectManager::get_instance()->resolve(sanitize_text_field((string)$r->get_param('project')));return is_wp_error($p)?new WP_Error('projectpress_rest_project_not_found',__('Project not found.','projectpress'),array('status'=>404)):$p;}private static function type(WP_REST_Request$r):string{return self::TYPES[sanitize_key((string)$r['type'])]??'component';}private static function repo(WP_REST_Request$r):CompositionRepository{return new CompositionRepository(self::type($r));}private static function service(WP_REST_Request$r,CompositionRepository$repo):CompositionService{return new CompositionService(self::type($r),$repo,ProjectManager::get_instance()->repository(),new ProjectPermissions());}
 private static function input(WP_REST_Request$r):array{return array('name'=>sanitize_text_field((string)$r->get_param('name')),'version'=>sanitize_text_field((string)$r->get_param('version')),'description'=>sanitize_textarea_field((string)$r->get_param('description')),'identifier'=>sanitize_text_field((string)$r->get_param('identifier')),'uri'=>esc_url_raw((string)$r->get_param('uri')),'licence'=>sanitize_text_field((string)$r->get_param('licence')),'source_type'=>sanitize_key((string)$r->get_param('source_type')),'source_id'=>absint($r->get_param('source_id')),'target_type'=>sanitize_key((string)$r->get_param('target_type')),'target_id'=>absint($r->get_param('target_id')),'relationship_type'=>sanitize_key((string)$r->get_param('relationship_type')),'format'=>sanitize_key((string)($r->get_param('format')?:'generic')),'payload'=>$r->get_param('payload')??array());}
 private static function success($data,int$status=200):WP_REST_Response{return new WP_REST_Response(array('success'=>true,'data'=>$data),$status);}private static function domain($x,int$status=200){return is_wp_error($x)?$x:self::success(is_object($x)&&method_exists($x,'to_array')?$x->to_array():$x,$status);}private static function forbidden():WP_Error{return new WP_Error('projectpress_rest_forbidden',__('You do not have permission to perform this action.','projectpress'),array('status'=>rest_authorization_required_code()));}private static function not_found(string$message):WP_Error{return new WP_Error('projectpress_composition_not_found',$message,array('status'=>404));}
}
